#include "start_art_owned.h"
#include "start_art_replace.h"
#include "obj_tiles_rgba.h"
typedef struct {TaxiOrdinaryGraphicsOwners *g;TaxiSpriteCopies *copies;TaxiSpriteImmediateCopy *dma;uint32_t source,destination;int error;} Context;
static uint32_t word(void *opaque,uint32_t a){Context *c=opaque;if(a<0x08000000){c->error=1;return 0;}size_t off=a-0x08000000;if(off>c->g->rom_size||c->g->rom_size-off<4){c->error=1;return 0;}const uint8_t *p=c->g->rom+off;return p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static int replace(void *opaque,uint32_t source,unsigned index,unsigned frame,unsigned group,unsigned immediate){Context *c=opaque;TaxiSpriteReplacementOwner o={c->g->rom,c->g->rom_size,0x08070e50,c->g->assets->bases,11,c->copies,c->dma,c->g->assets->objects,sizeof c->g->assets->objects,c->g->destination};return c->error?-1:taxi_sprite_replace_owned(&o,source,index,frame,group,immediate)<0?-1:0;}
static void write(void *opaque,uint32_t a,uint32_t v,unsigned n){Context *c=opaque;if(n!=4){c->error=1;return;}if(a==0x040000d4)c->source=v;else if(a==0x040000d8)c->destination=v;else if(a==0x040000dc){if(v!=0x80000010||c->destination!=0x05000360||c->source<0x08000000){c->error=1;return;}size_t off=c->source-0x08000000;if(off>c->g->rom_size||c->g->rom_size-off<32){c->error=1;return;}for(unsigned j=0;j<16;j++)c->g->banks->objects[176+j]=(uint16_t)(c->g->rom[off+2*j]|(uint16_t)c->g->rom[off+2*j+1]<<8);}else if(a==0x0200187c){for(unsigned j=0;j<4;j++)c->g->palette->records[11][16+j]=(uint8_t)(v>>(8*j));}else c->error=1;}
int taxi_start_art_replace_owned(TaxiOrdinaryGraphicsOwners *g,TaxiSpriteCopies *copies,TaxiSpriteImmediateCopy *dma,int16_t phase,uint8_t language){if(!g||!g->assets||!g->banks||!g->palette||g->palette->count<12||!g->rom||!copies||!dma)return -1;Context c={g,copies,dma,0,0,0};TaxiHudStartBackend b={&c,word,write,replace};int rc=taxi_start_art_replace(phase,language,&b);return rc||c.error?-1:0;}
int taxi_start_art_decode_owned(uint8_t out[3][4096],const TaxiOrdinaryGraphicsOwners *g){if(!out||!g||!g->assets||!g->banks||g->assets->bases[7]<0x06010000)return -1;uint32_t first=(g->assets->bases[7]-0x06010000)/32;for(unsigned j=0;j<3;j++){uint32_t tile=first+16*j;if(tile>1023||taxi_obj_tiles_rgba(out[j],4096,g->assets,g->banks,g->destination,(uint16_t)(tile|(11u<<12)),32,32))return -1;}return 0;}
